    FILE *w;
    w = fopen("f1", "w");
    if (w) {
        fputs("aaa!", w);
        fclose(w);
    }
    w = fopen("f2", "w");
    if (w) {
        fputs("bbb!", w);
        fclose(w);
    }
    w = fopen("f3", "w");
    if (w) {
        fputs("ccc!", w);
        fclose(w);
    }

    /* 原题命令行 e12_42 f1 f2 f3 → 等价自包含 argv */
    char *argv[] = {"e12_42", "f1", "f2", "f3"};
    int argc = 4;
    FILE *fp;
    int i = 1;
    while (--argc > 0)
        if ((fp = fopen(argv[i++], "r")) == NULL) {
            printf("Cannot open file !\n");
            exit(1);
        } else {
            sub(fp);
            fclose(fp);
        }
    return 0;
}

void sub(FILE *fp) {
    char c;
    while ((c = getc(fp)) != '!')
        putchar(c + 1);
}

