#define FILE_NAME "student.dat"

struct student {
    long int num;        /* 学号 */
    char name[10];       /* 姓名 */
    int age;             /* 年龄 */
    char sex;            /* 性别 */
    char speciality[20]; /* 专业 */
    char addr[40];       /* 住址 */
};

/* 判分环境下先按字段顺序从标准输入建好二进制文件 student.dat */
