    if (fp == NULL)
        return;
    while (scanf("%ld %9s %d %c %19s %39s", &s.num, s.name, &s.age, &s.sex, s.speciality, s.addr) ==
           6)
        fwrite(&s, sizeof(s), 1, fp);
    fclose(fp);
}

int main(void) {
    FILE *fp;
    struct student s;
    int found = 0;

    prepare_file();

    fp = fopen(FILE_NAME, "rb");
    if (fp == NULL) {
        printf("none\n");
        return 0;
    }
    while (fread(&s, sizeof(s), 1, fp) == 1) {
        if (s.num >= 40101 && s.num <= 40135) {
            printf("%06ld %s %d %c\n", s.num, s.name, s.age, s.sex);
            found = 1;
        }
    }
    fclose(fp);

    if (!found)
        printf("none\n");

    return 0;
}

