#include <stdio.h>
#include <stdlib.h>

struct Student {
    int num;
    int score;
};

int main(void) {
    FILE *fp, *bin;
    struct Student st[100], t;
    int c, n, i, j;

    fp = fopen("stu.txt", "w");
    if (fp == NULL)
        return 1;
    while ((c = getchar()) != EOF)
        fputc(c, fp);
    fclose(fp);

    if ((fp = fopen("stu.txt", "r")) == NULL) {
        printf("Cannot open file!\n");
        return 1;
    }
    if (fscanf(fp, "%d", &n) != 1 || n < 1 || n > 100) {
        fclose(fp);
        return 1;
    }
    for (i = 0; i < n; i++)
        if (fscanf(fp, "%d %d", &st[i].num, &st[i].score) != 2) {
            fclose(fp);
            return 1;
        }
    fclose(fp);

    if ((bin = fopen("stu.dat", "wb")) == NULL)
        return 1;
    if (fwrite(st, sizeof(struct Student), (size_t)n, bin) != (size_t)n) {
        fclose(bin);
        return 1;
    }
    fclose(bin);

    if ((bin = fopen("stu.dat", "rb")) == NULL)
        return 1;
    if (fread(st, sizeof(struct Student), (size_t)n, bin) != (size_t)n) {
        fclose(bin);
        return 1;
    }
    fclose(bin);

    for (i = 0; i < n - 1; i++)
        for (j = 0; j < n - 1 - i; j++)
            if (st[j].score < st[j + 1].score) {
                t = st[j];
                st[j] = st[j + 1];
                st[j + 1] = t;
            }

    for (i = 0; i < n; i++)
        printf("%d %d\n", st[i].num, st[i].score);
    return 0;
}

