#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    FILE *fp;
    char line[1024], best[1024];
    int c, len, bestlen = -1;

    fp = fopen("lines.txt", "w");
    if (fp == NULL)
        return 1;
    while ((c = getchar()) != EOF)
        fputc(c, fp);
    fclose(fp);

    if ((fp = fopen("lines.txt", "r")) == NULL) {
        printf("Cannot open file!\n");
        return 1;
    }
    best[0] = '\0';
    while (fgets(line, sizeof(line), fp) != NULL) {
        len = (int)strlen(line);
        while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r')) {
            len--;
            line[len] = '\0';
        }
        if (len > bestlen) {
            bestlen = len;
            strcpy(best, line);
        }
    }
    fclose(fp);

    if (bestlen < 0) {
        printf("0\n");
        return 0;
    }
    printf("%d\n%s\n", bestlen, best);
    return 0;
}

